static inline int32_t loud_shout_decode_reply(const td_wire_msg_t *m, const char **result, uint32_t *result_len) {
  td_wire_reader_t rd, *r = &rd;
  int32_t s = CROI_OK;
  uint64_t v;
  (void)s;
  (void)v;
  td_wire_arena_t *a = NULL;
  (void)a;
  if (td_wire_read_begin(r, m, 16) != CROI_OK) return TD_ERR_PROTOCOL;
  if (td_wire_load_string(r, 0, result, result_len) != CROI_OK) return TD_ERR_PROTOCOL;
  return td_wire_read_end(r);
}

// shout: calls the method (channel_call) and waits for its reply.
// buf holds the request, then the reply. Returns TD_ERR_REMOTE with *error_code set if
// the method failed.
static inline int32_t loud_shout(uint32_t channel, td_wire_msg_t *buf, int32_t *error_code, const char *text, uint32_t text_len, const char **result, uint32_t *result_len) {
  int32_t s = loud_shout_encode(buf, 0, text, text_len);
  if (s != CROI_OK) return s;
  if ((s = td_wire_call(channel, buf, buf, error_code)) != CROI_OK) return s;
  return loud_shout_decode_reply(buf, result, result_len);
}

// shouted (event): decodes it.
static inline int32_t loud_shouted_decode(const td_wire_msg_t *m, const char **text, uint32_t *text_len) {
  td_wire_reader_t rd, *r = &rd;
  int32_t s = CROI_OK;
  uint64_t v;
  (void)s;
  (void)v;
  td_wire_arena_t *a = NULL;
  (void)a;
  if (td_wire_read_begin(r, m, 16) != CROI_OK) return TD_ERR_PROTOCOL;
  if (td_wire_load_string(r, 0, text, text_len) != CROI_OK) return TD_ERR_PROTOCOL;
  return td_wire_read_end(r);
}

